begin; insert into public.admin_kv (key, value) select 'dml', '{}'::jsonb where exists (select 1 from information_schema.columns where table_name='admin_kv' and column_name='key');
create or replace function pg_temp.dml(rl text, claims text, stmt text) returns text language plpgsql as $f$ declare n int; begin execute 'set local role ' || rl; perform set_config('request.jwt.claims', claims, true); execute stmt; get diagnostics n = row_count; reset role; return 'rows=' || n; exception when others then reset role; return 'ERR:' || left(sqlerrm, 50); end $f$;
select r.role, s.stmt, pg_temp.dml(r.role, r.claims, s.stmt) from (values ('anon','{"role":"anon"}'),('authenticated','{"role":"authenticated","sub":"00000000-0000-0000-0000-0000000000aa","email":"attacker@example.test","aal":"aal1"}')) r(role,claims), (values ('select count(*) from public.admin_kv'),('delete from public.admin_kv'),('update public.admin_kv set value=''{"x":1}''::jsonb'),('insert into public.admin_kv (key,value) values (''evil'',''{}''::jsonb)')) s(stmt); rollback;
